SELECT
    user_id,
    arraySort(
        arrayDistinct(
            arrayFlatten(
                groupArray(
                    arrayFilter(tag -> positionCaseInsensitive(tag, 'premium') > 0, tags)
                )
            )
        )
    ) AS premium_tags
FROM events
GROUP BY user_id
HAVING notEmpty(premium_tags);

